var i=`yagni-you-aren-t-gonna-need-it`;var n=4;var o={en:[{id:`T004-Q01`,type:`single_choice`,difficulty:`foundation`,points:1,prompt:[{k:`p`,runs:[{t:`Which description best captures the main purpose of `},{t:`YAGNI — You Aren't Gonna Need It`,b:!0},{t:`?`}]}],options:[{id:`A`,text:`KISS favors the simplest design that satisfies known requirements and foreseeable risks.`},{id:`B`,text:`POLA says an interface should behave in ways its users reasonably expect.`},{id:`C`,text:`YAGNI discourages building features or abstractions for hypothetical future requirements.`},{id:`D`,text:`DRY means every piece of knowledge should have one authoritative representation.`}]},{id:`T004-Q02`,type:`single_choice`,difficulty:`applied`,points:1,prompt:[{k:`p`,runs:[{t:`Which implementation approach most directly applies `},{t:`YAGNI — You Aren't Gonna Need It`,b:!0},{t:`?`}]}],options:[{id:`A`,text:`SRP asks for one coherent reason to change; OCP prefers extension at stable variation points; LSP preserves behavioral contracts; ISP offers narrow consumer-oriented interfaces; DIP makes policy depend on abstractions rather than volatile implementations.`},{id:`B`,text:`Define boundaries around coherent policies and give each a narrow interface.`},{id:`C`,text:`Compare alternatives by number of components, states, exceptional paths, deployment steps, and cognitive overhead.`},{id:`D`,text:`Separate requirements that are committed, plausible, and speculative.`}]},{id:`T004-Q03`,type:`single_choice`,difficulty:`applied`,points:1,prompt:[{k:`p`,runs:[{t:`A team faces this situation: `},{t:`A single-country booking app does not need a full international tax engine on day one.`,b:!0},{t:` What is the most appropriate response?`}]}],options:[{id:`A`,text:`It should still store currency explicitly if changing that later would corrupt historical amounts.`},{id:`B`,text:`Separate pricing policy, payment gateway, and notification adapter; keep a small orchestration layer that coordinates a single order transaction.`},{id:`C`,text:`Testing each variant becomes straightforward.`},{id:`D`,text:`Expose a purpose-specific billing profile contract rather than sharing every internal field.`}]},{id:`T004-Q04`,type:`single_choice`,difficulty:`advanced`,points:1,prompt:[{k:`p`,runs:[{t:`When using `},{t:`YAGNI — You Aren't Gonna Need It`,b:!0},{t:`, which trade-off or common mistake deserves particular attention?`}]}],options:[{id:`A`,text:`Excessive interfaces, inheritance hierarchies, and dependency-injection plumbing make simple code harder to read.`},{id:`B`,text:`Types cannot express every runtime or cross-record invariant.`},{id:`C`,text:`Separating everything into network services creates latency and operational overhead.`},{id:`D`,text:`YAGNI must not excuse missing migrations, observability, backups, or compliance requirements.`}]},{id:`T004-Q05`,type:`true_false`,difficulty:`foundation`,points:1,prompt:[{k:`p`,runs:[{t:`Is the following statement accurate?`}]},{k:`quote`,runs:[{t:`It is an investment principle: defer uncertain complexity until there is evidence of demand.`}]}]},{id:`T004-Q06`,type:`true_false`,difficulty:`applied`,points:1,prompt:[{k:`p`,runs:[{t:`True or false?`}]},{k:`quote`,runs:[{t:`YAGNI means ignoring security and data integrity until users complain.`}]}]},{id:`T004-Q07`,type:`true_false`,difficulty:`advanced`,points:1,prompt:[{k:`p`,runs:[{t:`Is this guidance or caution accurate for the concept?`}]},{k:`quote`,runs:[{t:`Avoid confusing 'not needed now' with 'cheap to add later'; reversibility matters.`}]}]},{id:`T004-Q08`,type:`multiple_select`,difficulty:`applied`,points:2,prompt:[{k:`p`,runs:[{t:`Select `},{t:`exactly two`,b:!0},{t:` statements that correctly characterize `},{t:`YAGNI — You Aren't Gonna Need It`,b:!0},{t:`.`}]}],options:[{id:`A`,text:`Speculative features are more important than hard-to-reverse data decisions.`},{id:`B`,text:`YAGNI discourages building features or abstractions for hypothetical future requirements.`},{id:`C`,text:`Any repeated line of code violates DRY, even when the business rules differ.`},{id:`D`,text:`Separate requirements that are committed, plausible, and speculative.`}]},{id:`T004-Q09`,type:`multiple_select`,difficulty:`advanced`,points:2,prompt:[{k:`p`,runs:[{t:`Select `},{t:`exactly two`,b:!0},{t:` observations consistent with a sound application of `},{t:`YAGNI — You Aren't Gonna Need It`,b:!0},{t:`.`}]}],options:[{id:`A`,text:`KISS justifies skipping transaction boundaries when they complicate code.`},{id:`B`,text:`YAGNI means ignoring security and data integrity until users complain.`},{id:`C`,text:`It should still store currency explicitly if changing that later would corrupt historical amounts.`},{id:`D`,text:`Avoid confusing 'not needed now' with 'cheap to add later'; reversibility matters.`}]},{id:`T004-Q10`,type:`scenario_choice`,difficulty:`advanced`,points:2,prompt:[{k:`p`,runs:[{t:`An AI agent works on this task: `},{t:`A single-country booking app does not need a full international tax engine on day one.`,b:!0},{t:` Which proposed verification task most directly tests the required behavior?`}]}],options:[{id:`A`,text:`Refactor a checkout module with two payment providers. Preserve transaction behavior, add provider contract tests, explain which SOLID principles motivated each extraction, and avoid interfaces that have only one speculative use.`},{id:`B`,text:`Review a proposed generic plugin system for an MVP. Remove requirements unsupported by current users, list deferred decisions and document which choices are costly to reverse.`},{id:`C`,text:`Specify transfer preconditions, postconditions, invariant and error cases before generating any implementation. Ask the agent for transaction tests covering rollback and concurrency.`},{id:`D`,text:`Take a controller that validates, prices, persists, and emails an order. Propose responsibility boundaries, refactor without changing output, and test domain policy without an HTTP server.`}]},{id:`T004-Q11`,type:`short_answer`,difficulty:`advanced`,points:4,prompt:[{k:`p`,runs:[{t:`Which foundation is worth building early even when its related feature is not yet planned?`}]}]},{id:`T004-Q12`,type:`short_answer`,difficulty:`advanced`,points:4,prompt:[{k:`p`,runs:[{t:`In this situation — `},{t:`A single-country booking app does not need a full international tax engine on day one.`,b:!0},{t:` — what two specific signals would make you change the design used for `},{t:`YAGNI — You Aren't Gonna Need It`,b:!0},{t:`? Explain how you would measure them.`}]}]},{id:`T004-Q13`,type:`short_answer`,difficulty:`advanced`,points:4,prompt:[{k:`p`,runs:[{t:`For this case — `},{t:`A single-country booking app does not need a full international tax engine on day one.`,b:!0},{t:` — propose three checks for `},{t:`YAGNI — You Aren't Gonna Need It`,b:!0},{t:`: one normal case, one failure or boundary case, and one check for changing requirements. Give expected outcomes.`}]}]},{id:`T004-Q14`,type:`design_decision`,difficulty:`expert`,points:6,prompt:[{k:`p`,runs:[{t:`Design decision: `},{t:`A single-country booking app does not need a full international tax engine on day one.`,b:!0}]},{k:`p`,runs:[{t:`Describe your chosen approach, an alternative you rejected, the most important trade-off, and two concrete acceptance checks. Keep the proposal feasible for a real project.`}]}]},{id:`T004-Q15`,type:`ai_code_review`,difficulty:`expert`,points:6,prompt:[{k:`p`,runs:[{t:`Review an AI-generated change for `},{t:`YAGNI — You Aren't Gonna Need It`,b:!0},{t:`. The agent says the feature is complete for this situation: `},{t:`A single-country booking app does not need a full international tax engine on day one.`,b:!0},{t:`. It shows a successful demo, but its PR contains no explicit failure-case analysis or verification plan.`}]},{k:`p`,runs:[{t:`Identify at least `},{t:`two topic-specific risks`,b:!0},{t:`, propose the tests/evidence required before approval, and state whether you would approve, request changes, or block deployment. Explain why.`}]}]}],ua:[{id:`T004-Q01`,type:`single_choice`,difficulty:`foundation`,points:1,prompt:[{k:`p`,runs:[{t:`Яке формулювання найточніше передає призначення `},{t:`YAGNI — не реалізуй зайвого`,b:!0},{t:`?`}]}],options:[{id:`A`,text:`KISS віддає перевагу найпростішому дизайну, який виконує відомі вимоги та враховує реальні ризики.`},{id:`B`,text:`POLA означає, що інтерфейс має поводитися так, як користувач обґрунтовано очікує.`},{id:`C`,text:`YAGNI закликає не будувати функції та абстракції для вигаданих майбутніх вимог.`},{id:`D`,text:`DRY означає, що кожне правило або знання має одне авторитетне представлення.`}]},{id:`T004-Q02`,type:`single_choice`,difficulty:`applied`,points:1,prompt:[{k:`p`,runs:[{t:`Який спосіб реалізації найкраще відповідає `},{t:`YAGNI — не реалізуй зайвого`,b:!0},{t:`?`}]}],options:[{id:`A`,text:`SRP вимагає однієї узгодженої причини змін; OCP дозволяє розширення в точках варіативності; LSP зберігає поведінкові контракти; ISP пропонує вузькі інтерфейси; DIP відділяє політику від мінливих реалізацій.`},{id:`B`,text:`Проводьте межі навколо узгоджених політик і надавайте вузькі інтерфейси.`},{id:`C`,text:`Порівнюйте варіанти за кількістю компонентів, станів, виняткових шляхів, кроків розгортання та когнітивним навантаженням.`},{id:`D`,text:`Розділяйте підтверджені, ймовірні й суто гіпотетичні вимоги.`}]},{id:`T004-Q03`,type:`single_choice`,difficulty:`applied`,points:1,prompt:[{k:`p`,runs:[{t:`Команда має таку ситуацію: `},{t:`Сервіс бронювання для однієї країни не потребує глобального податкового рушія з першого дня.`,b:!0},{t:` Яке рішення найдоречніше?`}]}],options:[{id:`A`,text:`Але валюту варто зберігати явно, якщо інакше майбутні зміни пошкодять історичні суми.`},{id:`B`,text:`Відокремте правила ціни, платіжний шлюз та адаптер сповіщень; залиште невеликий оркестратор.`},{id:`C`,text:`Тестувати кожен варіант тоді простіше.`},{id:`D`,text:`Надайте цільовий контракт платіжного профілю замість відкриття всіх внутрішніх полів.`}]},{id:`T004-Q04`,type:`single_choice`,difficulty:`advanced`,points:1,prompt:[{k:`p`,runs:[{t:`Який компроміс або типову помилку особливо важливо врахувати під час застосування `},{t:`YAGNI — не реалізуй зайвого`,b:!0},{t:`?`}]}],options:[{id:`A`,text:`Надлишок інтерфейсів, ієрархій спадкування та DI-обв’язки ускладнює простий код.`},{id:`B`,text:`Типи не виражають усіх інваріантів виконання чи міжзаписних правил.`},{id:`C`,text:`Поділ на окремі мережеві сервіси додає затримки й операційні витрати.`},{id:`D`,text:`YAGNI не виправдовує відсутність міграцій, спостережуваності, резервних копій чи обов’язкової відповідності нормам.`}]},{id:`T004-Q05`,type:`true_false`,difficulty:`foundation`,points:1,prompt:[{k:`p`,runs:[{t:`Чи правильне твердження?`}]},{k:`quote`,runs:[{t:`Це принцип інвестицій: відкладіть сумнівну складність до появи доказів потреби.`}]}]},{id:`T004-Q06`,type:`true_false`,difficulty:`applied`,points:1,prompt:[{k:`p`,runs:[{t:`Правда чи неправда?`}]},{k:`quote`,runs:[{t:`YAGNI означає ігнорувати безпеку й цілісність даних, поки користувачі не поскаржаться.`}]}]},{id:`T004-Q07`,type:`true_false`,difficulty:`advanced`,points:1,prompt:[{k:`p`,runs:[{t:`Чи коректна ця порада або пересторога для цієї концепції?`}]},{k:`quote`,runs:[{t:`Не плутайте «не потрібно зараз» з «буде дешево додати потім».`}]}]},{id:`T004-Q08`,type:`multiple_select`,difficulty:`applied`,points:2,prompt:[{k:`p`,runs:[{t:`Оберіть `},{t:`рівно два`,b:!0},{t:` твердження, які правильно характеризують `},{t:`YAGNI — не реалізуй зайвого`,b:!0},{t:`.`}]}],options:[{id:`A`,text:`Гіпотетичні можливості важливіші за рішення щодо даних, які важко змінити.`},{id:`B`,text:`YAGNI закликає не будувати функції та абстракції для вигаданих майбутніх вимог.`},{id:`C`,text:`Будь-який повторений рядок коду порушує DRY, навіть коли бізнес-правила різні.`},{id:`D`,text:`Розділяйте підтверджені, ймовірні й суто гіпотетичні вимоги.`}]},{id:`T004-Q09`,type:`multiple_select`,difficulty:`advanced`,points:2,prompt:[{k:`p`,runs:[{t:`Оберіть `},{t:`рівно два`,b:!0},{t:` спостереження, що відповідають правильному застосуванню `},{t:`YAGNI — не реалізуй зайвого`,b:!0},{t:`.`}]}],options:[{id:`A`,text:`KISS виправдовує пропуск меж транзакцій, якщо вони ускладнюють код.`},{id:`B`,text:`YAGNI означає ігнорувати безпеку й цілісність даних, поки користувачі не поскаржаться.`},{id:`C`,text:`Але валюту варто зберігати явно, якщо інакше майбутні зміни пошкодять історичні суми.`},{id:`D`,text:`Не плутайте «не потрібно зараз» з «буде дешево додати потім».`}]},{id:`T004-Q10`,type:`scenario_choice`,difficulty:`advanced`,points:2,prompt:[{k:`p`,runs:[{t:`ШІ-агент працює над завданням: `},{t:`Сервіс бронювання для однієї країни не потребує глобального податкового рушія з першого дня.`,b:!0},{t:` Яка запропонована перевірка найкраще підтверджує потрібну поведінку?`}]}],options:[{id:`A`,text:`Відрефакторіть модуль оформлення з двома платіжними провайдерами. Збережіть поведінку транзакцій, додайте контрактні тести й поясніть кожне виділення через SOLID, не створюючи абстракцій для гіпотетичних сценаріїв.`},{id:`B`,text:`Перегляньте пропозицію універсальної системи плагінів для MVP. Приберіть вимоги без реального попиту, перелічіть відкладені рішення та позначте дорогі для перегляду.`},{id:`C`,text:`До генерації реалізації опишіть передумови, післяумови, інваріант і помилки переказу. Попросіть агента додати транзакційні тести відкату та конкурентного доступу.`},{id:`D`,text:`Візьміть контролер, який перевіряє, оцінює, записує та надсилає замовлення. Запропонуйте межі відповідальності, збережіть поведінку й протестуйте доменні правила без HTTP-сервера.`}]},{id:`T004-Q11`,type:`short_answer`,difficulty:`advanced`,points:4,prompt:[{k:`p`,runs:[{t:`У яку основу доцільно вкластися заздалегідь, навіть якщо відповідної фічі ще немає у плані?`}]}]},{id:`T004-Q12`,type:`short_answer`,difficulty:`advanced`,points:4,prompt:[{k:`p`,runs:[{t:`У ситуації `},{t:`Сервіс бронювання для однієї країни не потребує глобального податкового рушія з першого дня.`,b:!0},{t:` назвіть два конкретні сигнали, за яких ви змінили б рішення для `},{t:`YAGNI — не реалізуй зайвого`,b:!0},{t:`. Як саме їх виміряти?`}]}]},{id:`T004-Q13`,type:`short_answer`,difficulty:`advanced`,points:4,prompt:[{k:`p`,runs:[{t:`Для випадку `},{t:`Сервіс бронювання для однієї країни не потребує глобального податкового рушія з першого дня.`,b:!0},{t:` запропонуйте три перевірки `},{t:`YAGNI — не реалізуй зайвого`,b:!0},{t:`: типовий сценарій, збій або граничну умову та зміну вимог. Наведіть очікувані результати.`}]}]},{id:`T004-Q14`,type:`design_decision`,difficulty:`expert`,points:6,prompt:[{k:`p`,runs:[{t:`Архітектурне рішення: `},{t:`Сервіс бронювання для однієї країни не потребує глобального податкового рушія з першого дня.`,b:!0}]},{k:`p`,runs:[{t:`Опишіть обраний підхід, відхилену альтернативу, найважливіший компроміс і дві конкретні перевірки приймання. Рішення має бути практичним.`}]}]},{id:`T004-Q15`,type:`ai_code_review`,difficulty:`expert`,points:6,prompt:[{k:`p`,runs:[{t:`Перевірте зміну, згенеровану ШІ, з теми `},{t:`YAGNI — не реалізуй зайвого`,b:!0},{t:`. Агент стверджує, що функція готова для ситуації: `},{t:`Сервіс бронювання для однієї країни не потребує глобального податкового рушія з першого дня.`,b:!0},{t:`. Він показав успішне демо, але PR не містить аналізу збоїв або плану перевірок.`}]},{k:`p`,runs:[{t:`Назвіть щонайменше `},{t:`два ризики, специфічні для теми`,b:!0},{t:`, запропонуйте тести/докази перед погодженням і оберіть: погодити, повернути на доопрацювання чи заблокувати реліз. Обґрунтуйте рішення.`}]}]}]};var r={slug:i,topicId:4,questions:o};export{r as default,o as questions,i as slug,n as topicId};